from datetime import datetime

def parse_time(x):
  x_split = x.split(" ")
  str_time = " ".join(x_split[0 : -1])
  return datetime.strptime(str_time, "%Y/%m/%d %I:%M:%S %p")

df["Timestamp"] = df["Timestamp"].apply(lambda x: parse_time(x))
